import fs from 'node:fs';import puppeteer from 'puppeteer-core';
const base=(process.env.PUBLIC_BASE_URL||'https://diamondgatebridge.com').replace(/\/$/,'');const out=process.env.RUNTIME_RESULT_PATH||'/tmp/runtime-result.json';const chrome=process.env.CHROME_PATH;if(!chrome)throw new Error('CHROME_PATH is required');
const browser=await puppeteer.launch({executablePath:chrome,headless:'new',args:['--no-sandbox','--disable-dev-shm-usage']});const failures=[],checks=[];const add=(id,pass,evidence={})=>{checks.push({id,status:pass?'PASS':'FAIL',evidence});if(!pass)failures.push(id)};
const labels=async p=>p.evaluate(()=>[...document.querySelectorAll('[data-auren-options] .auren-option')].map(x=>x.textContent.trim()));
const click=async(p,t)=>{await p.waitForFunction(x=>[...document.querySelectorAll('[data-auren-options] .auren-option')].some(b=>b.textContent.trim()===x),{timeout:15000},t);await p.evaluate(x=>[...document.querySelectorAll('[data-auren-options] .auren-option')].find(b=>b.textContent.trim()===x)?.click(),t);await p.waitForFunction(()=>document.querySelector('[data-auren-chamber]')?.getAttribute('data-auren-options-ready')==='true',{timeout:15000});};
try{const page=await browser.newPage();await page.setViewport({width:390,height:844,deviceScaleFactor:1,isMobile:true,hasTouch:true});const errors=[];page.on('pageerror',e=>errors.push(String(e)));const response=await page.goto(base+'/products/auren/',{waitUntil:'networkidle0',timeout:60000});await page.waitForFunction(()=>document.querySelector('[data-auren-chamber]')?.getAttribute('data-auren-ready')==='true',{timeout:15000});await page.waitForFunction(()=>document.querySelector('[data-auren-chamber]')?.getAttribute('data-auren-options-ready')==='true',{timeout:15000});
let o=await labels(page);add('AUREN_ROUTE_READY',response?.status()===200,{status:response?.status(),url:page.url()});add('AUREN_OPENING_TWO_ENTRANCES',JSON.stringify(o)===JSON.stringify(['Products','About Auren']),{options:o});
await click(page,'Products');await click(page,'ARCHCOIN');await click(page,'What is ARCHCOIN?');o=await labels(page);const text=await page.evaluate(()=>document.querySelector('[data-auren-thread]')?.textContent||'');add('AUREN_ARCHCOIN_PROGRESSIVE_CORRIDOR',text.includes('What is ARCHCOIN?')&&text.includes('Two of those tokens are launched now')&&o.includes('Which ones are actually live?'),{options:o});
await click(page,'Which ones are actually live?');o=await labels(page);add('AUREN_ARCHCOIN_HANDOFF',o.includes('Take me to ARCHCOIN'),{options:o});
await page.reload({waitUntil:'networkidle0'});await page.waitForFunction(()=>document.querySelector('[data-auren-chamber]')?.getAttribute('data-auren-options-ready')==='true',{timeout:15000});await click(page,'About Auren');await click(page,'Who are you?');await click(page,'What do you protect?');o=await labels(page);add('AUREN_CHARACTER_PROGRESSIVE_CORRIDOR',o.includes('What are you protecting over there?'),{options:o});
await click(page,'What are you protecting over there?');const state=await page.evaluate(()=>document.querySelector('[data-auren-chamber]')?.getAttribute('data-custody-state'));add('AUREN_PROTECTED_REVEAL',state==='REVEALED',{custodyState:state});
const max=await page.evaluate(()=>document.querySelectorAll('[data-auren-options] .auren-option').length);add('AUREN_MAX_THREE_CONTEXTUAL_CHOICES',max<=3,{count:max});add('AUREN_NO_PAGE_ERRORS',errors.length===0,{errors});
}finally{await browser.close()}const result={status:failures.length?'FAIL':'PASS',checks,failures};fs.writeFileSync(out,JSON.stringify(result,null,2));console.log(JSON.stringify(result,null,2));if(failures.length)process.exitCode=1;